O = list(range(len(operations)))

c = [
    operations[o]["cost"]
    for o in O
]

V = [6, 8, 11, 13, 16, 18]

O_v = {
    v: [
        o for o in O
        if v in operations[o]["nodes"]
    ]
    for v in V
}

#print(O_v)
'''
for o in O:
    op = operations[o]
    print(f"{o}\n"
          f"{op["nodes"]}\n"
          f"{op["cost"]}\n")
'''
model = gp.Model("Agatz_TSPD")


# ---------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------

x = model.addVars(
    O,
    vtype=gp.GRB.BINARY,
    name="x"
)


#y = model.addVars(
#    V,
#    vtype=gp.GRB.BINARY,
#    name="y"
#)

# ---------------------------------------------------------
# OBJECTIVE
# ---------------------------------------------------------

model.setObjective(

    gp.quicksum(
        c[o] * x[o]
        for o in O
    ),

    sense=gp.GRB.MINIMIZE
)

# ========================================================
# (17) FLUX SUBTOUR ELIMINATION
# ========================================================




# =========================================================
# (17) MTZ - SUBTOUR ELIMINATION
# =========================================================

# Bounds for ordering variables
'''
model.addConstr(
    f[depot] == 0,
    name="mtz_depot"
)

model.addConstrs(
    (
        f[v] >= 1
        for v in V if v != depot
    ),
    name="mtz_lb"
)

model.addConstrs(
    (
        f[v] <= numVertices - 1
        for v in V if v != depot
    ),
    name="mtz_ub"
)

# MTZ constraints for operations

model.addConstrs(
    (
        f[operations[o]["start"]]
        - f[operations[o]["end"]]
        + numVertices * x[o]
        <= numVertices - 1

        for o in O

        if operations[o]["start"] != depot
        and operations[o]["end"] != depot
    ),
    name="mtz"
)
'''
#model.addConstr(
#    (
#        gp.quicksum(x[o] for o in O_v[depot]) == 2
#    )
#)

# =========================================================
# (14)
#
# Every node must belong to at least one selected operation
# =========================================================
model.addConstr(
    gp.quicksum(x[o] for o in O) >= 3
)


model.addConstrs(

    (
        gp.quicksum(
            x[o]
            for o in O_v[v]
        )
        >= 1

        for v in V
    ),

    name="cover"
)


# =========================================================
# (15)
# =========================================================
'''
model.addConstrs(

    (
        gp.quicksum(
            x[o]
            for o in O_plus_v[v]
        )
        <= numVertices * y[v]

        for v in V
    ),

    name="active"
)
'''

# =========================================================
# (16)
#
# Eulerian flow balance
# =========================================================
'''
model.addConstrs(

    (
        gp.quicksum(
            x[o]
            for o in O_plus_v[v]
        )

        ==

        gp.quicksum(
            x[o]
            for o in O_minus_v[v]
        )

        for v in V
    ),

    name="balance"
)
'''

# =========================================================
# GENERATE SUBSETS S
# =========================================================
'''
non_depot = [

    v for v in V

    if v != depot
]

subsets = []


for size in range(
        1,
        len(non_depot) + 1):

    for comb in combinations(
            non_depot,
            size):

        subsets.append(
            set(comb)
        )
'''

# =========================================================
# (17)
#
# Connectivity
# =========================================================
'''
for S in subsets:


    # O+(S):
    #
    # start OUTSIDE S
    # end INSIDE S

    O_plus_S = [

        o for o in O

        if operations[o]["end"] in S
        and operations[o]["start"] not in S
    ]


    for v in S:

        model.addConstr(

            gp.quicksum(
                x[o]
                for o in O_plus_S
            )

            >= y[v],

            name=
            "connect_"
            + "_".join(
                map(str, sorted(S))
            )
            + f"_v{v}"
        )

# =========================================================
# (18)
# =========================================================

model.addConstr(

    gp.quicksum(
        x[o]
        for o in O_plus_v[depot]
    )

    >= 1,

    name="depot_return"
)

'''
# =========================================================
# (19)
# =========================================================
'''
model.addConstr(

    y[depot] == 1,

    name="depot_active"
)
'''

# =========================================================
# SOLVE
# =========================================================

model.optimize()


# =========================================================
# PRINT SELECTED OPERATIONS
# =========================================================

if model.status == gp.GRB.OPTIMAL:

    print()
    print("==============================")
    print("OPTIMAL SOLUTION")
    print("==============================")
    print()

    print(
        "Total cost:",
        model.objVal
    )

    print()
    for o in O:
        if(x[o].X > 0.5):
            op = operations[o]
            print(f"Operation {o}\n"
                  f"{op["nodes"]}\n"
                  f"{op["cost"]}\n"
                  "==============\n")
            